<script setup lang="ts">
import {ref,shallowRef,onMounted,onUnmounted} from 'vue'
import {useRouter} from 'vue-router'
import {Upload,ArrowLeft} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import type {CharacterCard} from './card-format'
import {parseChatFile,importParsedChat,type ParsedChat} from './chat-import'
const store=useLocal(),router=useRouter(),cards=ref<Document<CharacterCard>[]>([]),parsed=shallowRef<ParsedChat|null>(null),mapping=ref<Record<string,string>>({}),error=ref(''),busy=ref(false),controller=new AbortController();let disposed=false
async function select(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{const result=await parseChatFile(file,controller.signal);if(disposed)return;parsed.value=result;mapping.value={};for(const key of result.participants){const exact=key.startsWith('identity:')?cards.value.find(row=>row.value.identityId===key.slice(9)):undefined,label=result.participantLabels[key],named=cards.value.filter(row=>row.value.name===label);mapping.value[key]=exact?.id||(named.length===1?named[0]!.id:cards.value.length===1?cards.value[0]!.id:'')};if(!result.participants.length&&cards.value.length===1)mapping.value['默认角色']=cards.value[0]!.id}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false;(event.target as HTMLInputElement).value=''}}
async function confirm(){const vault=store.vault,value=parsed.value;if(!vault||!value||busy.value)return;busy.value=true;error.value='';try{const id=await importParsedChat(vault,value,mapping.value,cards.value,controller.signal);if(disposed||store.vault!==vault||!vault.unlocked)return;await router.push('/local/chat/'+id)}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{const vault=store.vault;if(vault){const list=await vault.list<CharacterCard>('card');if(!disposed&&store.vault===vault)cards.value=list}}catch(e){if(!disposed)error.value=(e as Error).message}});onUnmounted(()=>{disposed=true;controller.abort();parsed.value=null})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">CONVERSATIONS</span><h1>导入对话</h1></div><RouterLink to="/local/characters" class="final-text-link"><ArrowLeft :size="18"/>返回角色</RouterLink></div><p v-if="error" role="alert" class="final-error">{{error}}</p><div v-if="!cards.length" class="final-empty"><h2>先为对话选择一个角色</h2><RouterLink to="/local/characters" class="final-primary">创建或导入角色</RouterLink></div><template v-else><label class="final-import-panel"><Upload :size="20"/>聊天 JSONL<input type="file" accept=".jsonl" :disabled="busy" @change="select"></label><section v-if="parsed" class="final-card-form" aria-label="对话导入预览"><h2>{{parsed.name}}</h2><p class="final-subtle">{{parsed.rows.length}} 条消息 · {{parsed.rows.reduce((sum,row)=>sum+row.variants.length,0)}} 个候选</p><label v-for="name in parsed.participants.length?parsed.participants:['默认角色']" :key="name">{{parsed.participantLabels[name]||name}}<select v-model="mapping[name]" :aria-label="'对应角色 '+name"><option value="">请选择角色</option><option v-for="card in cards" :key="card.id" :value="card.id">{{card.value.name}}</option></select></label><div class="final-import-panel"><article v-for="row in parsed.rows.slice(0,5)" :key="row.line"><strong>{{row.personaName||(row.participant?parsed.participantLabels[row.participant]:'旁白')}}</strong><p class="final-task-prose">{{row.text.slice(0,500)}}</p></article></div><div class="final-grid-actions"><button class="final-primary" :disabled="busy" @click="confirm">导入并打开</button><button :disabled="busy" @click="parsed=null;mapping={}">取消</button></div></section></template></section></template>
